            return builder.endVector()
        }
        fun startToolCallsVector(builder: FlatBufferBuilder, numElems: Int) = builder.startVector(4, numElems, 4)
        fun addEDGEHEADERS(builder: FlatBufferBuilder, edgeHeaders: Int) = builder.addOffset(80, edgeHeaders, 0)
        fun createEdgeHeadersVector(builder: FlatBufferBuilder, data: IntArray) : Int {
            builder.startVector(4, data.size, 4)
            for (i in data.size - 1 downTo 0) {
                builder.addOffset(data[i])
            }
            return builder.endVector()
        }
        fun startEdgeHeadersVector(builder: FlatBufferBuilder, numElems: Int) = builder.startVector(4, numElems, 4)
        fun endAIS(builder: FlatBufferBuilder) : Int {
            val o = builder.endTable()
                builder.required(o, 4)
                builder.required(o, 6)
            return o
        }
        fun finishAISBuffer(builder: FlatBufferBuilder, offset: Int) = builder.finish(offset, "\$AIS")
        fun finishSizePrefixedAISBuffer(builder: FlatBufferBuilder, offset: Int) = builder.finishSizePrefixed(offset, "\$AIS")
    }
}
